def transform(grid):
    sep = next(i for i, row in enumerate(grid) if all(v == 4 for v in row))
    top, bottom = grid[:sep], grid[sep + 1:]

    # The scattered marks in the upper and lower panels overlap to form the
    # output marks. Identify each panel's background as its most common color.
    def background(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return max(counts, key=counts.get)

    top_bg = background(top)
    bottom_bg = background(bottom)
    return [
        [3 if top[r][c] != top_bg and bottom[r][c] != bottom_bg else 5
         for c in range(len(top[r]))]
        for r in range(len(top))
    ]
